-- KIE reference prices (KIE credits, $0.005 each), documented on 2026-10-22. Inserting one re-prices the model under the
-- current global pricing policy (trigger policy_follow_change); customer prices are never written here.
insert into app_private.supplier_cost_versions (model_id, version, schedule, usd_per_credit, source_kind, source_url, source_checked_at, note)
select v.model_id, 1, v.schedule::jsonb, 0.005, 'documented', 'https://kie.ai/pricing', timestamptz '2026-10-22T12:00:00Z', v.note
from (values
  ('wan-2-6-flash', $j${"unit":"output","dims":["audio","resolution","duration"],"rates":{"off|720p|5":20,"off|720p|10":40,"off|720p|15":60,"on|720p|5":40,"on|720p|10":80,"on|720p|15":120,"off|1080p|5":30,"off|1080p|10":60,"off|1080p|15":90,"on|1080p|5":60,"on|1080p|10":120,"on|1080p|15":180}}$j$, 'KIE price list: wan 2.6 flash, image-to-video and video-to-video, per video by sound, resolution and length (720p 20/40/60 without, 40/80/120 with audio; 1080p 30/60/90 and 60/120/180 credits).'),
  ('wan-2-7', $j${"unit":"second","durationOption":"duration","dims":["resolution"],"rates":{"720p":16,"1080p":24}}$j$, 'KIE price list: wan 2.7 video, text-to-video / image-to-video / r2v, 720p/1080p = 16/24 credits per second.'),
